#include "horror/FontAtlas.hpp"
#include <algorithm>
#include <cctype>

namespace horror {
namespace {
constexpr std::array<int,64> SmallWidth{4,5,4,8,6,9,7,2,5,5,5,9,4,4,3,5,6,6,6,6,6,6,6,6,6,6,3,3,9,9,9,6,10,7,6,7,7,6,6,7,8,4,5,7,6,9,8,8,6,8,7,6,6,8,7,10,7,7,6,5,5,5,10,5};
constexpr std::array<int,64> LargeWidth{6,7,7,12,10,15,12,3,8,8,9,14,6,6,6,9,10,10,10,10,10,10,10,10,10,10,6,6,14,14,14,10,16,12,11,11,12,10,10,12,13,6,9,12,9,15,13,13,10,13,12,9,10,12,12,16,11,11,10,9,8,9,16,9};
// 2-bit grayscale atlases baked from user-supplied Annapurna SIL TTFs.
// These are glyph rasters (not font files). Encoded four pixels per byte.
constexpr const char* SmallPixels="";
constexpr const char* LargePixels="";
}
const FontAtlas& FontAtlas::instance(){
    static const FontAtlas font;
    return font;
}
char FontAtlas::normalize(char c) {
    const auto value=static_cast<unsigned char>(c);
    if(value>='a'&&value<='z')return static_cast<char>(value-32);
    if(value<32||value>95)return '?';
    return c;
}
std::vector<std::uint8_t> FontAtlas::unpack(std::string_view encoded) {
    std::vector<std::uint8_t> decoded;
    decoded.reserve(encoded.size()*3);
    unsigned value=0;
    int bits=0;
    for(char c:encoded) {
        if(c=='=')break;
        int k=-1;
        if(c>='A'&&c<='Z')k=c-'A';
        else if(c>='a'&&c<='z')k=c-'a'+26;
        else if(c>='0'&&c<='9')k=c-'0'+52;
        else if(c=='+')k=62;
        else if(c=='/')k=63;
        if(k<0)continue;
        value=(value<<6)|static_cast<unsigned>(k);
        bits+=6;
        if(bits>=8) {
            bits-=8;
            const unsigned byte=(value>>bits)&255u;
            decoded.push_back(static_cast<std::uint8_t>((byte>>6)&3u));
            decoded.push_back(static_cast<std::uint8_t>((byte>>4)&3u));
            decoded.push_back(static_cast<std::uint8_t>((byte>>2)&3u));
            decoded.push_back(static_cast<std::uint8_t>(byte&3u));
        }
    }
    return decoded;
}
FontAtlas::FontAtlas() {
    regular_.widths=SmallWidth;
    bold_.widths=LargeWidth;
    regular_.pixels=unpack(SmallPixels);
    bold_.pixels=unpack(LargePixels);
    std::size_t smallOffset=0,largeOffset=0;
    for(std::size_t i=0;i<64;++i) {
        regular_.offsets[i]=smallOffset;
        bold_.offsets[i]=largeOffset;
        smallOffset+=static_cast<std::size_t>(regular_.widths[i])*14;
        largeOffset+=static_cast<std::size_t>(bold_.widths[i])*21;
    }
}
int FontAtlas::glyphWidth(char letter,bool big) const {
    const Face& face=big?bold_:regular_;
    return face.widths[static_cast<unsigned char>(normalize(letter))-32];
}
int FontAtlas::textWidth(std::string_view text,bool big) const {
    int result=0;
    for(char c:text)result+=glyphWidth(c,big)+1;
    return result>0?result-1:0;
}
int FontAtlas::alpha(char letter,bool big,int x,int y) const {
    const Face& face=big?bold_:regular_;
    const unsigned index=static_cast<unsigned char>(normalize(letter))-32u;
    const int width=face.widths[index];
    if(x<0||x>=width||y<0||y>=(big?21:14))return 0;
    const std::size_t offset=face.offsets[index]+
        static_cast<std::size_t>(y)*static_cast<std::size_t>(width)+static_cast<std::size_t>(x);
    return offset<face.pixels.size()?face.pixels[offset]:0;
}
}
